"""Rectify two finite separator caps without moving original pavement.

In a local (x, y) frame each cap is a line x = c(y). The chart coordinate
s = L * (x - head(y)) / (tail(y) - head(y)) places the two caps at s=0,L.
Its inverse is x = head(y) + s/L * (tail(y) - head(y)). This permits tilted
or staggered free-end profiles with the existing direct-quad bridge. Both cap
widths and the longitudinal span must stay positive; the bridge additionally
checks original wire connectivity/monotonicity and all final physical quads.
"""
from . import boundary_quad_bridge_nodes as bridge


def construct(g,first,second,axis):
    pos=g.node('GeometryNodeInputPosition','Separator cap chart position').outputs[0]
    ac,bc=bridge._size(g,first),bridge._size(g,second)
    a0=g.sample(first,pos,0,'FLOAT_VECTOR');b0=g.sample(second,pos,0,'FLOAT_VECTOR')
    a1=g.sample(first,pos,g.math('SUBTRACT',ac,1.),'FLOAT_VECTOR')
    b1=g.sample(second,pos,g.math('SUBTRACT',bc,1.),'FLOAT_VECTOR')
    lateral=g.vector('CROSS_PRODUCT',(0.,0.,1.),axis)
    inverse_norm=g.math('DIVIDE',1.,g.vector('DOT_PRODUCT',axis,axis))
    def local(point):
        delta=g.vector('SUBTRACT',point,a0)
        return g.vector('DOT_PRODUCT',delta,axis),g.vector('DOT_PRODUCT',delta,lateral)
    xb0,yb0=local(b0);xa1,ya1=local(a1);xb1,yb1=local(b1)
    tail_gap=g.math('SUBTRACT',yb1,ya1)
    head_slope=g.math('DIVIDE',xb0,yb0)
    tail_slope=g.math('DIVIDE',g.math('SUBTRACT',xb1,xa1),tail_gap)
    length=g.math('MULTIPLY',.5,g.math('SUBTRACT',g.math('ADD',xa1,xb1),xb0))
    def extents(y):
        head=g.math('MULTIPLY',y,head_slope)
        tail=g.math('ADD',xa1,g.math('MULTIPLY',g.math('SUBTRACT',y,ya1),tail_slope))
        return head,g.math('SUBTRACT',tail,head)
    x,y=local(pos);head,span=extents(y)
    # Apply the small displacement from the original station. Multiplying and
    # dividing the full ~100 m coordinate twice needlessly loses float ulps
    # when a modest edit tilts an otherwise almost parallel pair of caps.
    correction=g.math('SUBTRACT',g.math('MULTIPLY',g.math('SUBTRACT',length,span),
        g.math('DIVIDE',g.math('SUBTRACT',x,head),span)),head)
    chart=g.xyz(g.math('ADD',x,correction),y,g.component(pos,'Z'))
    both=bridge._join(g,first,second)
    minimum_span=g.stat(both,span,output='Min')
    good=g.all(g.compare(yb0,1e-4,'GREATER_THAN'),g.compare(tail_gap,1e-4,'GREATER_THAN'),
               g.compare(length,1e-4,'GREATER_THAN'),g.compare(minimum_span,1e-4,'GREATER_THAN'))
    metrics=dict(cap_frame_minimum_span=minimum_span,cap_frame_head_gap=yb0,cap_frame_tail_gap=tail_gap)

    def restore(mesh):
        s=g.component(pos,'X');y=g.component(pos,'Y');head,span=extents(y)
        correction=g.math('ADD',head,g.math('MULTIPLY',g.math('DIVIDE',s,length),g.math('SUBTRACT',span,length)))
        x=g.math('ADD',s,correction)
        # Normalized float axes are not exactly unit length. Invert the actual
        # projection basis, including its squared norm, rather than multiplying
        # by the basis as though its norm were exactly one.
        world=g.vector('ADD',a0,g.vector('SCALE',g.vector('ADD',
            g.vector('SCALE',axis,x),g.vector('SCALE',lateral,y)),inverse_norm))
        physical=g.xyz(g.component(world,'X'),g.component(world,'Y'),g.component(pos,'Z'))
        side=g.named('_bridge_source_side');index=g.named('_bridge_source_index')
        original=g.switch(g.compare(side,0),g.sample(second,pos,index,'FLOAT_VECTOR'),
                          g.sample(first,pos,index,'FLOAT_VECTOR'),'VECTOR')
        pinned=g.compare(side,0,'GREATER_EQUAL')
        error=g.stat(mesh,g.switch(pinned,0.,g.vector('DISTANCE',physical,original)),output='Max')
        # Preserve original samples only after verifying the inverse mapping.
        result=bridge._position(g,mesh,g.switch(pinned,physical,original,'VECTOR'))
        return result,g.compare(error,bridge.TOLERANCE,'LESS_EQUAL'),error

    return bridge._position(g,first,chart),bridge._position(g,second,chart),good,metrics,restore
